import{z as n,x as s,o as B,c as d,q as A,j as t,D as a,d as e,s as r,S as o,b as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"视频生成的服务","description":"","frontmatter":{"title":"视频生成的服务","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/diff-video-serving.md","filePath":"llm/diff-video-serving.md","lastUpdated":1791413859000}'),p={name:"llm/diff-video-serving.md"};function D(m,E,C,f,h,c){const i=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=A('<h1 id="视频生成的服务" tabindex="-1">视频生成的服务 <a class="header-anchor" href="#视频生成的服务" aria-label="Permalink to &quot;视频生成的服务&quot;">​</a></h1><div class="epigraph"><p>把分钟的生成时间塞进秒级的请求-响应里，两边都输；视频服务的正确形状是作业：提交、排队、可取消、可查进度。</p><footer>—— 据 Blattmann 等 SVD（2023）与视频扩散服务实践整理</footer></div><p><a href="/llm/diff-control-serving">上一课</a>把条件变成可装配的对象，但单请求延迟仍是秒级。时间维把账放大一到两个数量级：算力是帧数 × 空间 × 步数，时空联合去噪的原理与长 clip 的漂移在<a href="/llm/video-gen-spatiotemporal">视频生成的时空建模</a>已立；本课只写服务形状的改变——从请求-响应改成作业系统，从秒级 SLO 改成分级进度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>视频请求的三条新约束压垮同步接口。其一，单 clip 生成从几十秒到几分钟，HTTP 同步等待必然超时，重试会造成重复扣算——一次几分钟的作业被网关超时杀掉重跑，是最贵的失败模式。其二，显存不再够整段激活：几十帧的时空注意力连同视频潜变量，单卡常放不下，需要分块解码与换出。其三，产品语义变了：用户要的不是「尽快拿到」，而是「知道还要多久、能取消、失败有交代」。缺口是把管线包装成有进度、有配额、可取消的异步作业，而不是把图像接口的超时调大。</p><h3 id="作业系统的形状" tabindex="-1">作业系统的形状 <a class="header-anchor" href="#作业系统的形状" aria-label="Permalink to &quot;作业系统的形状&quot;">​</a></h3><ul><li><strong>提交</strong>：返回作业号；请求规格（帧数、分辨率、步数、条件集）进队即冻结，防中途改参造成账目混乱。</li><li><strong>进度</strong>：去噪循环天然有 \\(T\\) 个刻度，按步上报进度；用户看到的「还有约 N 分钟」由队列位置与历史步时延折算。</li><li><strong>取消</strong>：取消点在批边界或步边界，与<a href="/llm/diff-batching-scheduling">批处理与调度</a>的让渡粒度一致；取消后立即释放批位，已计算的部分不留档。</li><li><strong>多级产物</strong>：先出低分辨率或首帧预览，再排队精修；时间到首预览与完成时间是两个独立 SLO。</li></ul><p><span class="marginnote">SVD 类模型一次生成 14 到 25 帧、分辨率到 576×1024；相对单张同分辨率图，token 数放大一个数量级以上，而步数并不减少——「帧数 × 空间 × 步数」三项是乘法，预算时一项都不能忘。</span></p><p><span class="marginnote">「幂等键」翻译一下：就是给每次提交发一张唯一编号的收据。网络超时后客户端拿同一张收据来重试，服务端一查「这个编号的作业已经在跑」，直接返回原作业号，不再新开一条——没有它，用户多点两次按钮，就多扣两次配额、多跑两遍几分钟的 GPU。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把生成拆成阶段图（DAG）而不是单作业：文生图定构图，图生视频做运动，插帧与超分做收尾。每个阶段独立排队、独立重试、独立计价；失败在阶段内重试，不重跑全链。视频潜变量与条件嵌入作为阶段间的产物落盘——阶段二的输入不必重算阶段一。显存按阶段预算：时空去噪激活最大，采取潜变量分块与激活换出；VAE 的时间维解码分块做，decoded 段即写存储，不在显存里攒整片。</p><p><span class="marginnote">显存为什么放不下，代个数字：图像潜变量约 \\(64\\times64\\times4\\)；视频 24 帧、每帧同尺寸，仅潜变量本体就乘上 24，时空注意力还要让每一帧和所有帧两两算相关，激活量随帧数接近平方增长。所以「多塞几帧」不是线性变慢，而是显存先爆——分块与换出就是把「一次性算完」改成「算一段、存一段」。</span></p>',12)),(B(),t(o,null,{default:a(()=>[r(i,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUB%5B%22%E6%8F%90%E4%BA%A4%E4%BD%9C%E4%B8%9A%EF%BC%9A%E8%A7%84%E6%A0%BC%E5%86%BB%E7%BB%93%22%5D%20--%3E%20Q%5B%22%E9%98%9F%E5%88%97%EF%BC%9A%E6%8C%89%E5%B8%A7%E6%95%B0%C3%97%E5%88%86%E8%BE%A8%E7%8E%87%E6%8A%98%E7%AE%97%E9%85%8D%E9%A2%9D%22%5D%0A%20%20Q%20--%3E%20T2I%5B%22%E9%98%B6%E6%AE%B5%E4%B8%80%EF%BC%9A%E6%96%87%E7%94%9F%E5%9B%BE%E5%AE%9A%E6%9E%84%E5%9B%BE%22%5D%0A%20%20T2I%20--%3E%20I2V%5B%22%E9%98%B6%E6%AE%B5%E4%BA%8C%EF%BC%9A%E5%9B%BE%E7%94%9F%E8%A7%86%E9%A2%91%EF%BC%8C%E6%BD%9C%E5%8F%98%E9%87%8F%E8%90%BD%E7%9B%98%22%5D%0A%20%20I2V%20--%3E%20UP%5B%22%E9%98%B6%E6%AE%B5%E4%B8%89%EF%BC%9A%E6%8F%92%E5%B8%A7%E4%B8%8E%E8%B6%85%E5%88%86%22%5D%0A%20%20T2I%20--%3E%7C%E5%A4%B1%E8%B4%A5%7C%20RET%5B%22%E9%98%B6%E6%AE%B5%E5%86%85%E9%87%8D%E8%AF%95%22%5D%0A%20%20I2V%20--%3E%7C%E5%A4%B1%E8%B4%A5%7C%20RET%0A%20%20UP%20--%3E%20OUT%5B%22%E4%BA%A7%E7%89%A9%E4%B8%8E%E6%B0%B4%E5%8D%B0%EF%BC%8C%E4%BD%9C%E4%B8%9A%E5%AE%8C%E6%88%90%22%5D%0A%20%20Q%20--%3E%7C%E7%94%A8%E6%88%B7%E5%8F%96%E6%B6%88%7C%20CAN%5B%22%E6%AD%A5%E8%BE%B9%E7%95%8C%E9%87%8A%E6%94%BE%E6%89%B9%E4%BD%8D%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l("h2",{id:"机制",tabindex:"-1"},[e("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=l("p",null,"为什么作业化不只是接口风格：计费、配额、容错都以「作业」为原子。图像时代「请求失败重试一次」的成本是一次前向；视频时代同口径的失误是一整段 GPU 时间，所以幂等键、去重与配额扣减都必须挂在作业号上。为什么阶段拆分省大钱：构图在低成本的图像模型上探索，运动合成只对选中的构图执行；不拆阶段的产品让用户为「不满意的构图」反复付费跑满整条视频管线。",-1)),(B(),t(o,null,{default:a(()=>[r(i,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20GO%5B%22%E7%94%A8%E6%88%B7%E6%8F%90%E4%BA%A4%E8%A7%86%E9%A2%91%E4%BD%9C%E4%B8%9A%22%5D%20--%3E%20WAIT%5B%22%E6%8E%92%E9%98%9F%E4%B8%8E%E5%8E%BB%E5%99%AA%E6%8E%A8%E8%BF%9B%22%5D%0A%20%20WAIT%20--%3E%20PV%5B%22%E9%A6%96%E5%B8%A7%20%2F%20%E4%BD%8E%E6%B8%85%E9%A2%84%E8%A7%88%E5%87%BA%E7%82%89%22%5D%0A%20%20PV%20--%3E%20J%7B%22%E7%94%A8%E6%88%B7%E7%9C%8B%E9%A2%84%E8%A7%88%E5%81%9A%E5%88%A4%E6%96%AD%22%7D%0A%20%20J%20--%3E%7C%E6%9E%84%E5%9B%BE%E4%B8%8D%E5%AF%B9%7C%20CAN%5B%22%E5%8F%96%E6%B6%88%EF%BC%9A%E6%AD%A5%E8%BE%B9%E7%95%8C%E9%87%8A%E6%94%BE%E6%89%B9%E4%BD%8D%22%5D%0A%20%20CAN%20--%3E%20RESUB%5B%22%E6%94%B9%E6%8F%90%E7%A4%BA%E8%AF%8D%E9%87%8D%E6%96%B0%E6%8F%90%E4%BA%A4%22%5D%0A%20%20RESUB%20--%3E%20GO%0A%20%20J%20--%3E%7C%E6%96%B9%E5%90%91%E5%AF%B9%7C%20FUL%5B%22%E6%8E%92%E9%98%9F%E8%BF%9B%E5%85%A5%E7%B2%BE%E4%BF%AE%E4%B8%8E%E8%B6%85%E5%88%86%22%5D%0A%20%20FUL%20--%3E%20DONE%5B%22%E5%AE%8C%E6%95%B4%E6%88%90%E7%89%87%E4%BA%A4%E4%BB%98%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=A('<p>为什么预览要单独一条 SLO：用户对「等」的容忍度取决于有没有反馈；首帧或低分辨率预览把主观等待切成两段，取消大多发生在预览之后——预览同时是用户体验和成本控制的共同支点。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重讲时空建模：时间注意力、潜变量视频与漂移对策见 <a href="/llm/video-gen-spatiotemporal">视频生成的时空建模</a>；服务侧只把「长 clip 会漂」翻译成产品约束——一次生成的 clip 长度有上限，长视频靠条件锚定分段拼接，不承诺单次生成任意长度。多卡切分（按帧或按时间维分片）解决放不下的极端作业，代价是通信与负载均衡复杂度，只在配额明确的大作业启用，不进通用队列。作业系统的可观测性沿用图像侧，但进度上报本身要限频，步时延波动大时进度条抖动会催生重复提交。</p><p><span class="marginnote">常见误区：初学者以为进度条越实时越好。实际上步时延本身有抖动，进度条按每步真实上报就会来回跳，用户一看「卡住了」就刷新或重复提交，反而制造了系统最怕的重复作业——所以上报要限频平滑，「看起来稳定」比「数值精确」更能保住队列健康。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>视频服务形状是异步作业：规格冻结、进度按步、取消在步边界、幂等键防重跑。</li><li>生成拆成 DAG：阶段独立排队重试计价，潜变量与条件落盘做阶段间交接。</li><li>成本按「帧数 × 空间 × 步数」三项乘法预算，token 数放大一个量级而步数不减。</li><li>时间到首预览与完成时间是两个 SLO，预览同时管体验与取消率。</li><li>显存靠分块解码与换出，多卡切分只给明确的大作业配额。</li><li>出处：Ho 等 Video Diffusion Models、Blattmann 等 SVD；作业系统口径据视频生成服务实践。</li></ul>',6))])}const g=n(p,[["render",D]]);export{u as __pageData,g as default};
